window.docContents[212].resolve({"/LindenstraussPolynomials/Compositions/#LindenstraussPolynomials___defc_chain":{"contents":"The claim eq:vcompositions, for chains ι 0 < ⋯ < ι D < ℓ. \n\n","context":"","header":"LindenstraussPolynomials.defc_chain","id":"/LindenstraussPolynomials/Compositions/#LindenstraussPolynomials___defc_chain"},"/LindenstraussPolynomials/Deficit/#LindenstraussPolynomials___defc_backward_iter":{"contents":"Iterating eq:vbackward: d_k^g(y) ≤ d_{k+N}^g(y) + 4 α_k². \n\n","context":"","header":"LindenstraussPolynomials.defc_backward_iter","id":"/LindenstraussPolynomials/Deficit/#LindenstraussPolynomials___defc_backward_iter"},"/LindenstraussPolynomials/Deficit/#mod-doc-LindenstraussPolynomials___Deficit-1-0":{"contents":"Deficits\n\nThe deficits d_k^g(y)=M_k-\\operatorname{Re}g(P_k\\,y) and the losses \\lambda_k=(1+\\alpha_k)M_k-M_{k+1} satisfy an exact identity under the perturbation (eq:vdeficit); from it come the backward estimate (eq:vbackward), the insertion estimate (eq:vinsert) and the bound on the losses (eq:loss).\n\n\n","context":"","header":"LindenstraussPolynomials.Deficit","id":"/LindenstraussPolynomials/Deficit/#mod-doc-LindenstraussPolynomials___Deficit-1-0"},"/LindenstraussPolynomials/Substitution/#mod-doc-LindenstraussPolynomials___Substitution-16-0":{"contents":"Expansion of `A((1-t)x + t w, …)` \n\n","context":"","header":"LindenstraussPolynomials.Substitution","id":"/LindenstraussPolynomials/Substitution/#mod-doc-LindenstraussPolynomials___Substitution-16-0"}});